        if width > 0 and height > 0:
            # Drift toward center if nothing else is known.
            return step_toward(self_pos, (width // 2, height // 2))
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    resource_cells = []
